const config = {
  "previewFeatures": [],
  "clientVersion": "7.10.1",
  "engineVersion": "d1b3f377ca835d73fd50954a5e22128b9ebdd6b8",
  "activeProvider": "postgresql",
  "inlineSchema": "generator client {\n  provider = \"prisma-client-js\"\n  output   = \"../src/generated/tenant\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n// ===== SHARED AUTHORIZATION ENUMS =====\n\nenum Persona {\n  STAFF\n  STUDENT\n  GUARDIAN\n}\n\nenum PermissionScope {\n  ALL\n  BRANCH\n  ASSIGNED\n  OWN\n}\n\nenum RoleKind {\n  SYSTEM_LOCKED\n  SYSTEM_EDITABLE\n  CUSTOM\n}\n\nenum MembershipStatus {\n  active\n  suspended\n  removed\n}\n\nenum StaffCategory {\n  teaching\n  non_teaching\n}\n\nenum EmploymentType {\n  full_time\n  part_time\n  contract\n  volunteer\n}\n\nenum NotificationChannel {\n  IN_APP\n  EMAIL\n  SMS\n}\n\nenum DeliveryStatus {\n  PENDING\n  QUEUED\n  SENT\n  DELIVERED\n  READ\n  FAILED\n  CANCELLED\n}\n\n// ===== PEOPLE =====\n\nmodel Staff {\n  id             String         @id @default(uuid())\n  userId         String?        @unique\n  employeeId     String?        @unique\n  firstName      String\n  lastName       String\n  middleName     String?\n  email          String?\n  phone          String?\n  photoUrl       String?\n  gender         Gender?\n  dateOfBirth    DateTime?\n  address        String?\n  department     String?\n  designation    String?\n  qualification  String?\n  category       StaffCategory  @default(non_teaching)\n  employmentType EmploymentType @default(full_time)\n  joinDate       DateTime?\n  exitDate       DateTime?\n  exitReason     String?\n  role           StaffRole      @default(other)\n  isActive       Boolean        @default(true)\n  createdById    String?\n  updatedById    String?\n  createdAt      DateTime       @default(now())\n  updatedAt      DateTime       @updatedAt\n  deletedAt      DateTime?\n\n  classSubjects         ClassSubject[]\n  classesAsClassTeacher Class[]\n  subjectDefaults       Subject[]      @relation(\"SubjectDefaultTeacher\")\n  branches              StaffBranch[]\n\n  @@index([isActive])\n  @@index([category])\n  @@index([email])\n  @@index([deletedAt])\n}\n\nenum StaffRole {\n  school_admin\n  principal\n  teacher\n  bursar\n  other\n}\n\nenum Gender {\n  male\n  female\n}\n\nmodel Student {\n  id              String    @id @default(uuid())\n  userId          String?   @unique\n  admissionNumber String?   @unique\n  firstName       String\n  lastName        String\n  middleName      String?\n  dateOfBirth     DateTime?\n  gender          Gender?\n  bloodGroup      String?\n  address         String?\n  photoUrl        String?\n  religion        String?\n  nationality     String?   @default(\"Nigerian\")\n  stateOfOrigin   String?\n  isActive        Boolean   @default(true)\n  graduatedAt     DateTime?\n  graduatedTermId String?\n  admittedAt      DateTime?\n  createdAt       DateTime  @default(now())\n  updatedAt       DateTime  @updatedAt\n\n  enrolments    Enrolment[]\n  guardianLinks StudentGuardian[]\n  attendances   Attendance[]\n  grades        Grade[]\n  feeInvoices   FeeInvoice[]\n  reportCards   ReportCard[]\n  discounts     StudentDiscount[]\n  allocations   PaymentAllocation[]\n  refunds       Refund[]\n\n  @@index([graduatedAt])\n}\n\nmodel Guardian {\n  id         String   @id @default(uuid())\n  userId     String?  @unique\n  firstName  String\n  lastName   String\n  email      String\n  phone      String?\n  occupation String?\n  address    String?\n  isActive   Boolean  @default(true)\n  createdAt  DateTime @default(now())\n  updatedAt  DateTime @updatedAt\n\n  studentLinks StudentGuardian[]\n  payments     Payment[]\n}\n\nmodel StudentGuardian {\n  id         String           @id @default(uuid())\n  studentId  String\n  guardianId String\n  relation   GuardianRelation\n  isPrimary  Boolean          @default(false)\n  createdAt  DateTime         @default(now())\n\n  student  Student  @relation(fields: [studentId], references: [id])\n  guardian Guardian @relation(fields: [guardianId], references: [id])\n\n  @@unique([studentId, guardianId])\n}\n\nenum GuardianRelation {\n  father\n  mother\n  uncle\n  aunt\n  grandparent\n  sibling\n  guardian\n  other\n}\n\n// ===== ACADEMIC =====\n\nmodel CalendarEvent {\n  id          String    @id @default(uuid())\n  termId      String?\n  sessionId   String?\n  title       String\n  description String?\n  startDate   DateTime\n  endDate     DateTime?\n  type        EventType @default(event)\n  isHoliday   Boolean   @default(false)\n  createdById String?\n  createdAt   DateTime  @default(now())\n  updatedAt   DateTime  @updatedAt\n\n  term    Term?    @relation(fields: [termId], references: [id])\n  session Session? @relation(fields: [sessionId], references: [id])\n\n  @@index([startDate])\n  @@index([termId])\n}\n\nenum EventType {\n  holiday\n  event\n  exam\n  break\n  other\n}\n\nmodel Session {\n  id        String   @id @default(uuid())\n  name      String\n  startDate DateTime\n  endDate   DateTime\n  isCurrent Boolean  @default(false)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  terms            Term[]\n  calendarEvents   CalendarEvent[]\n  journalEntries   JournalEntry[]\n  feeStructures    FeeStructure[]\n  feeInvoices      FeeInvoice[]\n  studentDiscounts StudentDiscount[]\n}\n\nmodel Term {\n  id        String   @id @default(uuid())\n  sessionId String\n  name      TermName\n  startDate DateTime\n  endDate   DateTime\n  isCurrent Boolean  @default(false)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  session        Session         @relation(fields: [sessionId], references: [id])\n  classSubjects  ClassSubject[]\n  attendances    Attendance[]\n  calendarEvents CalendarEvent[]\n  grades         Grade[]\n  feeInvoices    FeeInvoice[]\n  enrolments     Enrolment[]\n  reportCards    ReportCard[]\n  journalEntries JournalEntry[]\n  feeStructures  FeeStructure[]\n}\n\nenum TermName {\n  first\n  second\n  third\n}\n\nmodel Class {\n  id             String   @id @default(uuid())\n  name           String\n  level          String?\n  capacity       Int?\n  classTeacherId String?\n  createdAt      DateTime @default(now())\n  updatedAt      DateTime @updatedAt\n\n  classTeacher     Staff?             @relation(fields: [classTeacherId], references: [id])\n  enrolments       Enrolment[]\n  classSubjects    ClassSubject[]\n  progressionsFrom ClassProgression[] @relation(\"ProgressionFrom\")\n  progressionsTo   ClassProgression[] @relation(\"ProgressionTo\")\n  feeStructures    FeeStructure[]\n  feeInvoices      FeeInvoice[]\n  attendance       Attendance[]\n}\n\nmodel Subject {\n  id               String   @id @default(uuid())\n  name             String\n  code             String?  @unique\n  description      String?\n  defaultTeacherId String?\n  createdAt        DateTime @default(now())\n  updatedAt        DateTime @updatedAt\n\n  defaultTeacher Staff?         @relation(\"SubjectDefaultTeacher\", fields: [defaultTeacherId], references: [id])\n  classSubjects  ClassSubject[]\n}\n\nmodel ClassSubject {\n  id          String                       @id @default(uuid())\n  classId     String\n  subjectId   String\n  staffId     String\n  termId      String\n  assignedVia ClassSubjectAssignmentSource @default(manual)\n  createdAt   DateTime                     @default(now())\n  updatedAt   DateTime                     @updatedAt\n\n  class   Class        @relation(fields: [classId], references: [id])\n  subject Subject      @relation(fields: [subjectId], references: [id])\n  staff   Staff        @relation(fields: [staffId], references: [id])\n  term    Term         @relation(fields: [termId], references: [id])\n  grades  Grade[]\n  sheet   ResultSheet?\n\n  @@unique([classId, subjectId, termId])\n}\n\nenum ClassSubjectAssignmentSource {\n  manual\n  auto_subject_default\n  auto_homeroom\n}\n\nmodel Enrolment {\n  id        String          @id @default(uuid())\n  studentId String\n  classId   String\n  termId    String\n  status    EnrolmentStatus @default(active)\n  createdAt DateTime        @default(now())\n  updatedAt DateTime        @updatedAt\n\n  student Student @relation(fields: [studentId], references: [id])\n  class   Class   @relation(fields: [classId], references: [id])\n  term    Term    @relation(fields: [termId], references: [id])\n\n  @@unique([studentId, termId])\n}\n\nenum EnrolmentStatus {\n  active\n  withdrawn\n  transferred\n  completed\n}\n\nmodel ClassProgression {\n  id          String   @id @default(uuid())\n  fromClassId String   @unique\n  toClassId   String?\n  fromClass   Class    @relation(\"ProgressionFrom\", fields: [fromClassId], references: [id])\n  toClass     Class?   @relation(\"ProgressionTo\", fields: [toClassId], references: [id])\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n}\n\nenum TeachingModel {\n  homeroom\n  subject_specialist\n}\n\n// ===== SCHOOL SETTINGS =====\n\nmodel SchoolSettings {\n  id                        String         @id @default(uuid())\n  logoUrl                   String?\n  primaryColor              String?        @default(\"#1a1a2e\")\n  secondaryColor            String?\n  motto                     String?\n  address                   String?\n  website                   String?\n  foundedYear               Int?\n  principalName             String?\n  stamp                     String?\n  reportCardTemplate        String         @default(\"classic\")\n  reportCardLetterheadUrl   String?\n  letterheadContentTopMm    Int?           @default(50)\n  letterheadContentBottomMm Int?           @default(30)\n  allowStudentLogin         Boolean        @default(false)\n  signature                 String?\n  createdAt                 DateTime       @default(now())\n  updatedAt                 DateTime       @updatedAt\n  teachingModel             TeachingModel?\n}\n\n// ===== ATTENDANCE =====\n\nmodel Attendance {\n  id         String           @id @default(uuid())\n  studentId  String\n  termId     String\n  classId    String? // the class the register was taken for (old rows: empty)\n  date       DateTime\n  status     AttendanceStatus\n  note       String?\n  markedById String? // the LOGIN (User) id of who marked it (old rows: empty)\n  createdAt  DateTime         @default(now())\n  updatedAt  DateTime         @updatedAt\n\n  student Student @relation(fields: [studentId], references: [id])\n  term    Term    @relation(fields: [termId], references: [id])\n  class   Class?  @relation(fields: [classId], references: [id], onDelete: SetNull)\n\n  @@unique([studentId, date])\n  @@index([classId, date])\n  @@index([termId, date])\n}\n\nenum AttendanceStatus {\n  present\n  absent\n  late\n  excused\n}\n\n// ===== GRADES AND REPORT CARDS =====\n\nmodel Grade {\n  id             String   @id @default(uuid())\n  studentId      String\n  termId         String\n  classSubjectId String\n  sheetId        String\n  caScore        Float?\n  examScore      Float?\n  total          Float?\n  grade          String?\n  remark         String?\n  position       Int?\n  totalStudents  Int?\n  isPublished    Boolean  @default(false)\n  createdAt      DateTime @default(now())\n  updatedAt      DateTime @updatedAt\n\n  student      Student      @relation(fields: [studentId], references: [id])\n  term         Term         @relation(fields: [termId], references: [id])\n  classSubject ClassSubject @relation(fields: [classSubjectId], references: [id])\n  sheet        ResultSheet  @relation(fields: [sheetId], references: [id])\n  scores       GradeScore[]\n\n  @@unique([studentId, termId, classSubjectId])\n  @@index([sheetId])\n}\n\nmodel GradingConfig {\n  id        String   @id @default(uuid())\n  minScore  Float\n  maxScore  Float\n  grade     String\n  remark    String\n  isDefault Boolean  @default(false)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\nmodel ReportCard {\n  id              String           @id @default(uuid())\n  studentId       String\n  termId          String\n  status          ReportCardStatus @default(draft)\n  teacherRemark   String?\n  principalRemark String?\n  totalScore      Float?\n  averageScore    Float?\n  position        Int?\n  totalStudents   Int?\n  pdfUrl          String?\n  emailSentAt     DateTime?\n  smsSentAt       DateTime?\n  generatedAt     DateTime?\n  createdAt       DateTime         @default(now())\n  updatedAt       DateTime         @updatedAt\n\n  student Student @relation(fields: [studentId], references: [id])\n  term    Term    @relation(fields: [termId], references: [id])\n\n  @@unique([studentId, termId])\n}\n\nenum ReportCardStatus {\n  draft\n  generated\n  published\n  sent\n}\n\n// ===== FEES AND PAYMENTS (v2) =====\n// Money is BigInt kobo. Every invoice, payment, adjustment and refund posts to the books\n// (see the ledger module); these tables hold the school-facing records.\n\nenum FeeStudentType {\n  ALL\n  NEW\n  RETURNING\n}\n\nenum InvoiceType {\n  TERM_FEES\n  ADMISSION\n  ADHOC\n  OPENING_BALANCE\n}\n\n// draft: not yet visible to parents and not in the books. void: cancelled after issue (journal reversed).\nenum InvoiceStatus {\n  draft\n  unpaid\n  partial\n  paid\n  waived\n  void\n}\n\nenum FeeDiscountType {\n  PERCENT\n  FIXED\n}\n\nenum FeeDiscountKind {\n  SIBLING\n  STAFF_CHILD\n  SCHOLARSHIP\n  EARLY_PAYMENT\n  CUSTOM\n}\n\nenum AdjustmentType {\n  WAIVER\n  WRITE_OFF\n  CREDIT_NOTE\n  ADDITIONAL_DISCOUNT\n}\n\nenum InvoiceAdjustmentStatus {\n  PENDING\n  APPROVED\n  REJECTED\n}\n\nenum InstalmentPlanStatus {\n  ACTIVE\n  COMPLETED\n  CANCELLED\n}\n\nenum PaymentPayerType {\n  GUARDIAN\n  STUDENT\n  OTHER\n}\n\nenum PaymentMethod {\n  paystack\n  flutterwave\n  bank_transfer\n  cash\n  cheque\n  pos\n  other\n}\n\nenum FeePaymentStatus {\n  PENDING\n  AWAITING_CONFIRMATION\n  CONFIRMED\n  FAILED\n  REVERSED\n}\n\nenum RefundStatus {\n  REQUESTED\n  APPROVED\n  PAID\n  REJECTED\n}\n\n// A kind of fee (tuition, uniform ...). Its income account is where money earned lands.\nmodel FeeType {\n  id              String    @id @default(uuid())\n  code            String    @unique\n  name            String\n  description     String?\n  incomeAccountId String\n  isRefundable    Boolean   @default(false)\n  isActive        Boolean   @default(true)\n  sortOrder       Int       @default(0)\n  createdById     String?\n  createdAt       DateTime  @default(now())\n  updatedAt       DateTime  @updatedAt\n  deletedAt       DateTime?\n\n  incomeAccount        LedgerAccount        @relation(fields: [incomeAccountId], references: [id], onDelete: Restrict)\n  structureItems       FeeStructureItem[]\n  invoiceItems         FeeInvoiceItem[]\n  discountRules        FeeDiscountRule[]\n  invoiceDiscountLines FeeInvoiceDiscount[]\n\n  @@index([incomeAccountId])\n  @@index([isActive])\n  @@index([deletedAt])\n}\n\n// What a class (or every class) is charged for one term.\nmodel FeeStructure {\n  id          String         @id @default(uuid())\n  name        String\n  sessionId   String\n  termId      String\n  classId     String?\n  branchId    String?\n  studentType FeeStudentType @default(ALL)\n  dueDate     DateTime?      @db.Date\n  description String?\n  isActive    Boolean        @default(true)\n  createdById String?\n  updatedById String?\n  createdAt   DateTime       @default(now())\n  updatedAt   DateTime       @updatedAt\n  deletedAt   DateTime?\n\n  session  Session            @relation(fields: [sessionId], references: [id], onDelete: Restrict)\n  term     Term               @relation(fields: [termId], references: [id], onDelete: Restrict)\n  class    Class?             @relation(fields: [classId], references: [id], onDelete: Restrict)\n  branch   Branch?            @relation(fields: [branchId], references: [id], onDelete: Restrict)\n  items    FeeStructureItem[]\n  invoices FeeInvoice[]\n\n  @@index([termId, classId])\n  @@index([sessionId])\n  @@index([branchId])\n  @@index([deletedAt])\n}\n\nmodel FeeStructureItem {\n  id          String   @id @default(uuid())\n  structureId String\n  feeTypeId   String\n  amountKobo  BigInt\n  sortOrder   Int      @default(0)\n  createdAt   DateTime @default(now())\n\n  structure FeeStructure @relation(fields: [structureId], references: [id], onDelete: Cascade)\n  feeType   FeeType      @relation(fields: [feeTypeId], references: [id], onDelete: Restrict)\n\n  @@unique([structureId, feeTypeId])\n  @@index([feeTypeId])\n}\n\n// A bill to one student. Amounts are kept on the row and checked by the database:\n// total = subtotal - discount + adjustments, balance = total - paid.\n// invoiceNumber is given when the invoice is issued, never before.\nmodel FeeInvoice {\n  id                 String        @id @default(uuid())\n  invoiceNumber      String?       @unique\n  type               InvoiceType   @default(TERM_FEES)\n  studentId          String\n  sessionId          String?\n  termId             String?\n  classId            String?\n  branchId           String?\n  sourceStructureId  String?\n  lateFeeOfInvoiceId String?       @unique\n  status             InvoiceStatus @default(draft)\n  issueDate          DateTime?     @db.Date\n  dueDate            DateTime?     @db.Date\n  subtotalKobo       BigInt        @default(0)\n  discountKobo       BigInt        @default(0)\n  adjustmentsKobo    BigInt        @default(0)\n  totalKobo          BigInt        @default(0)\n  paidKobo           BigInt        @default(0)\n  balanceKobo        BigInt        @default(0)\n  journalId          String?       @unique\n  note               String?\n  version            Int           @default(1)\n  voidedAt           DateTime?\n  voidedById         String?\n  voidReason         String?\n  createdById        String?\n  updatedById        String?\n  createdAt          DateTime      @default(now())\n  updatedAt          DateTime      @updatedAt\n\n  student         Student              @relation(fields: [studentId], references: [id], onDelete: Restrict)\n  session         Session?             @relation(fields: [sessionId], references: [id], onDelete: Restrict)\n  term            Term?                @relation(fields: [termId], references: [id], onDelete: Restrict)\n  class           Class?               @relation(fields: [classId], references: [id], onDelete: Restrict)\n  branch          Branch?              @relation(fields: [branchId], references: [id], onDelete: Restrict)\n  sourceStructure FeeStructure?        @relation(fields: [sourceStructureId], references: [id], onDelete: Restrict)\n  journal         JournalEntry?        @relation(fields: [journalId], references: [id], onDelete: Restrict)\n  items           FeeInvoiceItem[]\n  discounts       FeeInvoiceDiscount[]\n  adjustments     InvoiceAdjustment[]\n  allocations     PaymentAllocation[]\n  instalmentPlan  InstalmentPlan?\n  lateFeeOf       FeeInvoice?          @relation(\"LateFee\", fields: [lateFeeOfInvoiceId], references: [id], onDelete: Restrict)\n  lateFee         FeeInvoice?          @relation(\"LateFee\")\n\n  @@index([studentId, status])\n  @@index([termId, status])\n  @@index([status, dueDate])\n  @@index([branchId])\n  @@index([sourceStructureId])\n}\n\n// A line on an invoice. Description and income account are copied at the time, so a later\n// change to the fee type never rewrites an old invoice.\nmodel FeeInvoiceItem {\n  id              String   @id @default(uuid())\n  invoiceId       String\n  feeTypeId       String?\n  description     String\n  incomeAccountId String\n  amountKobo      BigInt\n  sortOrder       Int      @default(0)\n  createdAt       DateTime @default(now())\n\n  invoice       FeeInvoice          @relation(fields: [invoiceId], references: [id], onDelete: Cascade)\n  feeType       FeeType?            @relation(fields: [feeTypeId], references: [id], onDelete: Restrict)\n  incomeAccount LedgerAccount       @relation(fields: [incomeAccountId], references: [id], onDelete: Restrict)\n  adjustments   InvoiceAdjustment[]\n\n  @@index([invoiceId])\n  @@index([feeTypeId])\n  @@index([incomeAccountId])\n}\n\n// A discount taken off one invoice, with the rule it came from. The label is copied, so renaming a rule\n// never rewrites an old invoice. The invoice's discountKobo is the sum of these lines.\nmodel FeeInvoiceDiscount {\n  id         String   @id @default(uuid())\n  invoiceId  String\n  ruleId     String?\n  feeTypeId  String?\n  label      String\n  amountKobo BigInt\n  createdAt  DateTime @default(now())\n\n  invoice FeeInvoice       @relation(fields: [invoiceId], references: [id], onDelete: Cascade)\n  rule    FeeDiscountRule? @relation(fields: [ruleId], references: [id], onDelete: Restrict)\n  feeType FeeType?         @relation(fields: [feeTypeId], references: [id], onDelete: Restrict)\n\n  @@index([invoiceId])\n  @@index([ruleId])\n}\n\n// A reusable discount (sibling, staff child, scholarship ...). feeTypeId empty = whole invoice.\n// value is basis points for PERCENT (1000 = 10%) and kobo for FIXED.\nmodel FeeDiscountRule {\n  id          String          @id @default(uuid())\n  name        String\n  kind        FeeDiscountKind @default(CUSTOM)\n  type        FeeDiscountType\n  value       BigInt\n  feeTypeId   String?\n  isActive    Boolean         @default(true)\n  createdById String?\n  createdAt   DateTime        @default(now())\n  updatedAt   DateTime        @updatedAt\n  deletedAt   DateTime?\n\n  feeType          FeeType?             @relation(fields: [feeTypeId], references: [id], onDelete: Restrict)\n  students         StudentDiscount[]\n  invoiceDiscounts FeeInvoiceDiscount[]\n\n  @@index([isActive])\n  @@index([deletedAt])\n}\n\n// Gives one student a discount rule, for a session or for good (sessionId empty).\nmodel StudentDiscount {\n  id          String    @id @default(uuid())\n  studentId   String\n  ruleId      String\n  sessionId   String?\n  note        String?\n  createdById String?\n  createdAt   DateTime  @default(now())\n  deletedAt   DateTime?\n\n  student Student         @relation(fields: [studentId], references: [id], onDelete: Restrict)\n  rule    FeeDiscountRule @relation(fields: [ruleId], references: [id], onDelete: Restrict)\n  session Session?        @relation(fields: [sessionId], references: [id], onDelete: Restrict)\n\n  @@index([studentId])\n  @@index([ruleId])\n  @@index([sessionId])\n}\n\n// A change to an issued invoice (waiver, write-off, credit note, extra discount).\n// Needs a second person to approve; the books are touched only on approval.\n// amountKobo is always positive; the type says which way it moves the invoice.\nmodel InvoiceAdjustment {\n  id                String                  @id @default(uuid())\n  invoiceId         String\n  type              AdjustmentType\n  invoiceItemId     String?\n  amountKobo        BigInt\n  reason            String\n  status            InvoiceAdjustmentStatus @default(PENDING)\n  requestedById     String\n  decidedById       String?\n  decidedAt         DateTime?\n  decisionNote      String?\n  firstApprovedById String?\n  firstApprovedAt   DateTime?\n  journalId         String?                 @unique\n  createdAt         DateTime                @default(now())\n  updatedAt         DateTime                @updatedAt\n\n  invoice     FeeInvoice      @relation(fields: [invoiceId], references: [id], onDelete: Restrict)\n  invoiceItem FeeInvoiceItem? @relation(fields: [invoiceItemId], references: [id], onDelete: Restrict)\n  journal     JournalEntry?   @relation(fields: [journalId], references: [id], onDelete: Restrict)\n\n  @@index([invoiceId])\n  @@index([invoiceItemId])\n  @@index([status])\n}\n\nmodel InstalmentPlan {\n  id          String               @id @default(uuid())\n  invoiceId   String               @unique\n  status      InstalmentPlanStatus @default(ACTIVE)\n  createdById String?\n  createdAt   DateTime             @default(now())\n  updatedAt   DateTime             @updatedAt\n\n  invoice FeeInvoice       @relation(fields: [invoiceId], references: [id], onDelete: Restrict)\n  lines   InstalmentLine[]\n}\n\nmodel InstalmentLine {\n  id         String   @id @default(uuid())\n  planId     String\n  lineNumber Int\n  dueDate    DateTime @db.Date\n  amountKobo BigInt\n\n  plan InstalmentPlan @relation(fields: [planId], references: [id], onDelete: Cascade)\n\n  @@unique([planId, lineNumber])\n  @@index([dueDate])\n}\n\n// Money received. It does not belong to one invoice: allocations say where it went,\n// and what is not allocated stays as the payer's credit (unallocatedKobo).\nmodel Payment {\n  id                String           @id @default(uuid())\n  payerType         PaymentPayerType @default(GUARDIAN)\n  guardianId        String?\n  payerName         String?\n  payerPhone        String?\n  branchId          String?\n  method            PaymentMethod\n  channel           String?\n  amountKobo        BigInt\n  unallocatedKobo   BigInt           @default(0)\n  accountId         String\n  status            FeePaymentStatus @default(PENDING)\n  reference         String?          @unique\n  gatewayReference  String?\n  webhookVerified   Boolean          @default(false)\n  providerResponse  Json?\n  proofAttachmentId String?\n  targetStudentIds  String[]         @default([])\n  clientRequestId   String?          @unique\n  note              String?\n  paidAt            DateTime?\n  recordedById      String?\n  confirmedById     String?\n  confirmedAt       DateTime?\n  journalId         String?          @unique\n  reversedAt        DateTime?\n  reversedById      String?\n  reversalReason    String?\n  version           Int              @default(1)\n  createdAt         DateTime         @default(now())\n  updatedAt         DateTime         @updatedAt\n\n  guardian        Guardian?              @relation(fields: [guardianId], references: [id], onDelete: Restrict)\n  branch          Branch?                @relation(fields: [branchId], references: [id], onDelete: Restrict)\n  account         LedgerAccount          @relation(fields: [accountId], references: [id], onDelete: Restrict)\n  proofAttachment Attachment?            @relation(fields: [proofAttachmentId], references: [id], onDelete: Restrict)\n  journal         JournalEntry?          @relation(fields: [journalId], references: [id], onDelete: Restrict)\n  allocations     PaymentAllocation[]\n  refunds         Refund[]\n  receipt         Receipt?\n  settlementItem  GatewaySettlementItem?\n\n  @@index([status])\n  @@index([guardianId])\n  @@index([accountId])\n  @@index([branchId])\n  @@index([createdAt])\n}\n\n// Part of a payment applied to one invoice. invoiceId empty = held as the student's credit.\nmodel PaymentAllocation {\n  id          String    @id @default(uuid())\n  paymentId   String\n  invoiceId   String?\n  studentId   String\n  amountKobo  BigInt\n  reversedAt  DateTime?\n  createdById String?\n  createdAt   DateTime  @default(now())\n\n  payment Payment     @relation(fields: [paymentId], references: [id], onDelete: Restrict)\n  invoice FeeInvoice? @relation(fields: [invoiceId], references: [id], onDelete: Restrict)\n  student Student     @relation(fields: [studentId], references: [id], onDelete: Restrict)\n\n  @@index([paymentId])\n  @@index([invoiceId])\n  @@index([studentId])\n}\n\nmodel Refund {\n  id                String       @id @default(uuid())\n  paymentId         String\n  studentId         String?\n  amountKobo        BigInt\n  reason            String\n  status            RefundStatus @default(REQUESTED)\n  payoutAccountId   String?\n  requestedById     String\n  decidedById       String?\n  decidedAt         DateTime?\n  decisionNote      String?\n  firstApprovedById String?\n  firstApprovedAt   DateTime?\n  paidAt            DateTime?\n  journalId         String?      @unique\n  createdAt         DateTime     @default(now())\n  updatedAt         DateTime     @updatedAt\n\n  payment       Payment        @relation(fields: [paymentId], references: [id], onDelete: Restrict)\n  student       Student?       @relation(fields: [studentId], references: [id], onDelete: Restrict)\n  payoutAccount LedgerAccount? @relation(\"RefundPayoutAccount\", fields: [payoutAccountId], references: [id], onDelete: Restrict)\n  journal       JournalEntry?  @relation(fields: [journalId], references: [id], onDelete: Restrict)\n\n  @@index([paymentId])\n  @@index([status])\n  @@index([studentId])\n}\n\n// The receipt handed to the payer. The snapshot is frozen when issued.\nmodel Receipt {\n  id            String   @id @default(uuid())\n  receiptNumber String   @unique\n  paymentId     String   @unique\n  issuedAt      DateTime @default(now())\n  snapshot      Json\n  createdAt     DateTime @default(now())\n\n  payment Payment @relation(fields: [paymentId], references: [id], onDelete: Restrict)\n}\n\n// ===== SCHOOL ROLE MANAGEMENT =====\n\nmodel SchoolRole {\n  id                    String    @id @default(uuid())\n  name                  String\n  description           String?\n  kind                  RoleKind\n  persona               Persona   @default(STAFF)\n  grantsAll             Boolean   @default(false)\n  sourceTemplateKey     String?\n  sourceTemplateVersion Int?\n  isCustomized          Boolean   @default(false)\n  createdById           String?\n  createdAt             DateTime  @default(now())\n  updatedAt             DateTime  @updatedAt\n  deletedAt             DateTime?\n\n  permissions SchoolRolePermission[]\n  members     MembershipRole[]\n\n  @@index([sourceTemplateKey])\n}\n\nmodel SchoolRolePermission {\n  roleId        String\n  permissionKey String\n  scope         PermissionScope @default(ALL)\n\n  role SchoolRole @relation(fields: [roleId], references: [id], onDelete: Cascade)\n\n  @@id([roleId, permissionKey])\n  @@index([permissionKey])\n}\n\n// One row per portal account per persona. Contact-only guardians and students\n// without logins do not need a membership.\n\nmodel Membership {\n  id              String           @id @default(uuid())\n  userId          String\n  persona         Persona\n  personaEntityId String\n  status          MembershipStatus @default(active)\n  createdAt       DateTime         @default(now())\n  updatedAt       DateTime         @updatedAt\n\n  roles MembershipRole[]\n\n  @@unique([userId, persona])\n  @@unique([persona, personaEntityId])\n  @@index([userId])\n  @@index([status])\n}\n\nmodel MembershipRole {\n  membershipId String\n  roleId       String\n  assignedAt   DateTime @default(now())\n  assignedById String?\n\n  membership Membership @relation(fields: [membershipId], references: [id], onDelete: Cascade)\n  role       SchoolRole @relation(fields: [roleId], references: [id])\n\n  @@id([membershipId, roleId])\n  @@index([roleId])\n}\n\n// ===== BRANCH MANAGEMENT =====\n\nmodel Branch {\n  id               String    @id @default(uuid())\n  name             String\n  code             String    @unique\n  isMain           Boolean   @default(false)\n  address          String?\n  city             String?\n  state            String?\n  phone            String?\n  email            String?\n  principalStaffId String?\n  isActive         Boolean   @default(true)\n  createdById      String?\n  createdAt        DateTime  @default(now())\n  updatedAt        DateTime  @updatedAt\n  deletedAt        DateTime?\n\n  staff          StaffBranch[]\n  journalEntries JournalEntry[]\n  feeStructures  FeeStructure[]\n  feeInvoices    FeeInvoice[]\n  payments       Payment[]\n\n  @@index([isActive])\n  @@index([deletedAt])\n}\n\n// Where a staff member works. This table also determines which branches\n// their BRANCH-scoped roles may access.\n\nmodel StaffBranch {\n  staffId      String\n  branchId     String\n  isPrimary    Boolean  @default(false)\n  assignedAt   DateTime @default(now())\n  assignedById String?\n\n  staff  Staff  @relation(fields: [staffId], references: [id], onDelete: Cascade)\n  branch Branch @relation(fields: [branchId], references: [id])\n\n  @@id([staffId, branchId])\n  @@index([branchId])\n}\n\n// ===== SCHOOL SETTINGS OVERRIDES =====\n\n// One row per overridden key. Deleting the row restores the platform default.\n\nmodel SchoolSettingValue {\n  key         String   @id\n  value       Json\n  updatedById String?\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n}\n\n// ===== AUTOMATION =====\n\nmodel AutomationRule {\n  id            String                @id @default(uuid())\n  definitionKey String\n  name          String\n  enabled       Boolean               @default(false)\n  params        Json\n  channels      NotificationChannel[]\n  audience      Json?\n  templateKey   String?\n  schedule      Json?\n  lastRunAt     DateTime?\n  nextRunAt     DateTime?\n  createdById   String?\n  updatedById   String?\n  createdAt     DateTime              @default(now())\n  updatedAt     DateTime              @updatedAt\n  deletedAt     DateTime?\n\n  runs AutomationRunLog[]\n\n  @@index([definitionKey])\n  @@index([enabled, nextRunAt])\n}\n\nmodel AutomationRunLog {\n  id             String              @id @default(uuid())\n  ruleId         String\n  triggeredAt    DateTime            @default(now())\n  trigger        String\n  status         AutomationRunStatus\n  matched        Int                 @default(0)\n  notified       Int                 @default(0)\n  skippedReason  String?\n  error          String?\n  notificationId String?\n\n  rule AutomationRule @relation(fields: [ruleId], references: [id], onDelete: Cascade)\n\n  @@index([ruleId, triggeredAt])\n}\n\nenum AutomationRunStatus {\n  SUCCESS\n  PARTIAL\n  FAILED\n  SKIPPED\n}\n\n// ===== SCHOOL MESSAGE TEMPLATES =====\n\nmodel SchoolMessageTemplate {\n  id          String              @id @default(uuid())\n  key         String\n  channel     NotificationChannel\n  locale      String              @default(\"en\")\n  subject     String?\n  body        String\n  isActive    Boolean             @default(true)\n  updatedById String?\n  createdAt   DateTime            @default(now())\n  updatedAt   DateTime            @updatedAt\n\n  @@unique([key, channel, locale])\n  @@index([isActive])\n}\n\n// ===== NUMBER SEQUENCES =====\n\n// Gapless per-school counters for admission numbers, invoices, receipts, and payslips.\n// The period resets a counter; an empty string means the counter never resets.\n\nmodel NumberSequence {\n  key       String\n  period    String   @default(\"\")\n  nextValue Int      @default(1)\n  updatedAt DateTime @updatedAt\n\n  @@id([key, period])\n}\n\n// ===== ATTACHMENTS =====\n\n// Shared file metadata for student and staff documents, receipts, payslips, and letters.\n// sizeBytes can be used as the storage entitlement meter source.\n\nmodel Attachment {\n  id           String    @id @default(uuid())\n  ownerType    String\n  ownerId      String\n  kind         String\n  fileName     String\n  fileUrl      String\n  mimeType     String?\n  sizeBytes    Int       @default(0)\n  uploadedById String?\n  createdAt    DateTime  @default(now())\n  deletedAt    DateTime?\n\n  paymentProofs Payment[]\n\n  @@index([ownerType, ownerId])\n  @@index([deletedAt])\n}\n\n// ===== SCHOOL NOTIFICATIONS =====\n\nmodel SchoolNotification {\n  id         String                 @id @default(uuid())\n  title      String\n  message    String\n  type       SchoolNotificationType\n  targetType TargetType\n  sentById   String\n  metadata   Json?\n  sentAt     DateTime?\n  createdAt  DateTime               @default(now())\n  updatedAt  DateTime               @updatedAt\n\n  recipients SchoolNotificationRecipient[]\n\n  @@index([type])\n  @@index([createdAt(sort: Desc)])\n}\n\nmodel SchoolNotificationRecipient {\n  id                String               @id @default(uuid())\n  notificationId    String\n  recipientType     RecipientType\n  recipientEntityId String\n  userId            String?\n  channel           NotificationChannel\n  status            DeliveryStatus       @default(PENDING)\n  priority          NotificationPriority @default(NORMAL)\n  retryCount        Int                  @default(0)\n  failedReason      String?\n  providerMsgId     String?\n  idempotencyKey    String?              @unique\n  queuedAt          DateTime?\n  sentAt            DateTime?\n  failedAt          DateTime?\n  cancelledAt       DateTime?\n  nextRetryAt       DateTime?\n  readAt            DateTime?\n  deliveredAt       DateTime?\n  createdAt         DateTime             @default(now())\n  updatedAt         DateTime             @updatedAt\n\n  notification SchoolNotification @relation(fields: [notificationId], references: [id], onDelete: Cascade)\n\n  @@unique([notificationId, channel, recipientType, recipientEntityId])\n  @@index([status])\n  @@index([status, priority, createdAt])\n  @@index([recipientType, recipientEntityId])\n}\n\nenum SchoolNotificationType {\n  fee_invoice\n  fee_reminder\n  fee_receipt\n  report_card_ready\n  attendance_alert\n  event\n  holiday\n  broadcast\n  custom\n}\n\nenum RecipientType {\n  STUDENT\n  GUARDIAN\n  STAFF\n}\n\nenum NotificationPriority {\n  LOW\n  NORMAL\n  HIGH\n  CRITICAL\n}\n\nenum TargetType {\n  STUDENT\n  GUARDIAN\n  STAFF\n  ALL_PARENTS\n  ALL_STUDENTS\n  ALL_STAFF\n  EVERYONE\n}\n\n// ===========================================================================\n// FINANCE: THE BOOKS  (owned by the Finance workspace; see FINANCE_MODULE_BRIEF.md)\n// Money is whole kobo in BigInt. Accounting dates are calendar dates (DATE), so a Nigerian\n// midnight never slips to the day before. A posted journal can never be edited or deleted\n// (database triggers in the finance_books migration); a mistake is fixed by a reversal.\n// Only the finance workspace edits this block. The back-relation lines this block needs\n// (journalEntries on Branch, Term and Session) are the only edits outside it.\n// ===========================================================================\n\nenum LedgerAccountType {\n  ASSET\n  LIABILITY\n  EQUITY\n  INCOME\n  EXPENSE\n}\n\nenum JournalStatus {\n  POSTED\n  REVERSED\n}\n\nenum PeriodStatus {\n  OPEN\n  CLOSED\n}\n\nenum JournalSourceType {\n  FEE_INVOICE\n  PAYMENT\n  REFUND\n  ADJUSTMENT\n  EXPENSE_BILL\n  EXPENSE_PAYMENT\n  PAYROLL_ACCRUAL\n  PAYROLL_PAYMENT\n  PAYROLL_REMITTANCE\n  TRANSFER\n  OPENING_BALANCE\n  MANUAL\n  REVERSAL\n}\n\n// Who a journal line is about, so reports can show who owes what\nenum LedgerPartyType {\n  STUDENT\n  GUARDIAN\n  VENDOR\n  STAFF\n}\n\n// A labeled bucket in the school's books: Cash, Tuition Income, Salaries ...\n// One chart of accounts per school (branches share it; a journal records its branch).\nmodel LedgerAccount {\n  id                 String            @id @default(uuid())\n  code               String            @unique\n  name               String\n  type               LedgerAccountType\n  subtype            String            @default(\"GENERAL\")\n  systemKey          String?           @unique\n  parentId           String?\n  description        String?\n  isMoneyAccount     Boolean           @default(false)\n  bankName           String?\n  accountName        String?\n  accountNumberLast4 String?\n  isActive           Boolean           @default(true)\n  isLocked           Boolean           @default(false)\n  sortOrder          Int               @default(0)\n  createdById        String?\n  updatedById        String?\n  createdAt          DateTime          @default(now())\n  updatedAt          DateTime          @updatedAt\n  deletedAt          DateTime?\n\n  parent   LedgerAccount?  @relation(\"LedgerAccountTree\", fields: [parentId], references: [id], onDelete: Restrict)\n  children LedgerAccount[] @relation(\"LedgerAccountTree\")\n  lines    JournalLine[]\n\n  feeTypes      FeeType[]\n  invoiceItems  FeeInvoiceItem[]\n  payments      Payment[]\n  refundPayouts Refund[]         @relation(\"RefundPayoutAccount\")\n\n  expenseLines     ExpenseLine[]\n  expensePayFrom   Expense[]          @relation(\"ExpensePayFrom\")\n  expensePayments  ExpensePayment[]\n  budgetLines      BudgetLine[]\n  recurringPayFrom RecurringExpense[] @relation(\"RecurringPayFrom\")\n\n  bankStatements      BankStatement[]\n  bankMatchGroups     BankMatchGroup[]\n  bankReconciliations BankReconciliation[]\n  gatewaySettlements  GatewaySettlement[]\n  salaryTransfersFrom SalaryTransfer[]     @relation(\"SalaryTransferFrom\")\n\n  @@index([type])\n  @@index([parentId])\n  @@index([isActive])\n  @@index([deletedAt])\n}\n\n// An accounting month. A closed period cannot receive postings.\nmodel FinancePeriod {\n  id           String       @id @default(uuid())\n  name         String       @unique\n  startDate    DateTime     @unique @db.Date\n  endDate      DateTime     @db.Date\n  status       PeriodStatus @default(OPEN)\n  closedAt     DateTime?\n  closedById   String?\n  reopenedAt   DateTime?\n  reopenedById String?\n  reopenReason String?\n  createdAt    DateTime     @default(now())\n  updatedAt    DateTime     @updatedAt\n\n  journals            JournalEntry[]\n  bankReconciliations BankReconciliation[]\n}\n\n// One money event. Immutable once posted; only status may change (POSTED to REVERSED).\n// idempotencyKey is built by the posting service from source type, source id and purpose,\n// so the same event can never post twice. A reversal points back at the journal it undoes.\nmodel JournalEntry {\n  id             String            @id @default(uuid())\n  number         String            @unique\n  entryDate      DateTime          @db.Date\n  periodId       String\n  termId         String?\n  sessionId      String?\n  branchId       String?\n  description    String\n  sourceType     JournalSourceType\n  sourceId       String?\n  purpose        String\n  idempotencyKey String            @unique\n  status         JournalStatus     @default(POSTED)\n  reversalOfId   String?           @unique\n  reversalReason String?\n  totalKobo      BigInt\n  createdById    String?\n  isSystemActor  Boolean           @default(false)\n  postedAt       DateTime          @default(now())\n  createdAt      DateTime          @default(now())\n\n  period     FinancePeriod @relation(fields: [periodId], references: [id], onDelete: Restrict)\n  term       Term?         @relation(fields: [termId], references: [id], onDelete: Restrict)\n  session    Session?      @relation(fields: [sessionId], references: [id], onDelete: Restrict)\n  branch     Branch?       @relation(fields: [branchId], references: [id], onDelete: Restrict)\n  reversalOf JournalEntry? @relation(\"JournalReversal\", fields: [reversalOfId], references: [id], onDelete: Restrict)\n  reversedBy JournalEntry? @relation(\"JournalReversal\")\n  lines      JournalLine[]\n\n  feeInvoice        FeeInvoice?\n  payment           Payment?\n  gatewaySettlement GatewaySettlement?\n  salaryTransfer    SalaryTransfer?    @relation(\"SalaryTransferJournal\")\n  adjustment        InvoiceAdjustment?\n  refund            Refund?\n  expense           Expense?\n  expensePayment    ExpensePayment?\n  runAccrual        PayrollRun?        @relation(\"RunAccrual\")\n  runPayment        PayrollRun?        @relation(\"RunPayment\")\n  loanDisbursed     StaffLoan?\n  remittance        PayrollRemittance?\n\n  @@index([periodId])\n  @@index([entryDate])\n  @@index([sourceType, sourceId])\n  @@index([termId])\n  @@index([branchId])\n}\n\n// One account moved by a journal, on the debit side or the credit side (never both).\n// The database enforces: exactly one side above zero, and debits equal credits per journal.\nmodel JournalLine {\n  id              String           @id @default(uuid())\n  journalId       String\n  lineNumber      Int\n  ledgerAccountId String\n  debitKobo       BigInt           @default(0)\n  creditKobo      BigInt           @default(0)\n  memo            String?\n  partyType       LedgerPartyType?\n  partyId         String?\n\n  journal       JournalEntry            @relation(fields: [journalId], references: [id], onDelete: Restrict)\n  ledgerAccount LedgerAccount           @relation(fields: [ledgerAccountId], references: [id], onDelete: Restrict)\n  bankMatch     BankMatchedJournalLine?\n\n  @@unique([journalId, lineNumber])\n  @@index([ledgerAccountId, journalId])\n  @@index([partyType, partyId])\n}\n\n// ===== FINANCE: EXPENSES, BILLS AND BUDGETS (phase 3) =====\n\nenum ExpenseKind {\n  DIRECT // paid at once, when approved\n  BILL // owed to a supplier; paid later, in one or more payments\n}\n\nenum ExpenseStatus {\n  DRAFT\n  PENDING_APPROVAL\n  APPROVED\n  PARTIALLY_PAID\n  PAID\n  REJECTED\n  VOID\n}\n\nenum RecurrenceFrequency {\n  WEEKLY\n  MONTHLY\n  TERMLY\n  YEARLY\n}\n\nenum BudgetStatus {\n  DRAFT\n  ACTIVE\n  CLOSED\n}\n\n// A supplier. The bank account number is stored encrypted; only the last four digits are shown.\nmodel Vendor {\n  id                     String    @id @default(uuid())\n  name                   String\n  contactName            String?\n  phone                  String?\n  email                  String?\n  address                String?\n  bankName               String?\n  accountName            String?\n  accountNumberEncrypted String?\n  accountNumberLast4     String?\n  taxId                  String?\n  notes                  String?\n  isActive               Boolean   @default(true)\n  createdById            String?\n  updatedById            String?\n  createdAt              DateTime  @default(now())\n  updatedAt              DateTime  @updatedAt\n  deletedAt              DateTime?\n\n  expenses          Expense[]\n  recurringExpenses RecurringExpense[]\n\n  @@index([name])\n  @@index([isActive])\n  @@index([deletedAt])\n}\n\n// Money the school spends. DIRECT is paid when approved; BILL is owed to the supplier (accounts payable) until paid.\n// The number is given when it is submitted, so drafts leave no gaps. Amounts are whole kobo.\nmodel Expense {\n  id                 String        @id @default(uuid())\n  expenseNumber      String?       @unique\n  kind               ExpenseKind\n  vendorId           String?\n  reference          String?\n  description        String\n  expenseDate        DateTime      @db.Date\n  dueDate            DateTime?     @db.Date\n  totalKobo          BigInt\n  paidKobo           BigInt        @default(0)\n  status             ExpenseStatus @default(DRAFT)\n  payFromAccountId   String?\n  termId             String?\n  branchId           String?\n  recurringExpenseId String?\n  requestedById      String\n  submittedAt        DateTime?\n  approvedById       String?\n  approvedAt         DateTime?\n  firstApprovedById  String?\n  firstApprovedAt    DateTime?\n  autoApproved       Boolean       @default(false)\n  rejectedById       String?\n  rejectedAt         DateTime?\n  rejectionReason    String?\n  voidReason         String?\n  voidedById         String?\n  voidedAt           DateTime?\n  journalId          String?       @unique\n  version            Int           @default(1)\n  createdAt          DateTime      @default(now())\n  updatedAt          DateTime      @updatedAt\n\n  vendor         Vendor?           @relation(fields: [vendorId], references: [id], onDelete: Restrict)\n  payFromAccount LedgerAccount?    @relation(\"ExpensePayFrom\", fields: [payFromAccountId], references: [id], onDelete: Restrict)\n  recurring      RecurringExpense? @relation(fields: [recurringExpenseId], references: [id], onDelete: Restrict)\n  journal        JournalEntry?     @relation(fields: [journalId], references: [id], onDelete: Restrict)\n  lines          ExpenseLine[]\n  payments       ExpensePayment[]\n\n  @@unique([recurringExpenseId, expenseDate]) // a repeat run never makes the same expense twice\n  @@index([status])\n  @@index([kind])\n  @@index([vendorId])\n  @@index([expenseDate])\n  @@index([dueDate])\n  @@index([requestedById])\n  @@index([recurringExpenseId])\n}\n\nmodel ExpenseLine {\n  id              String @id @default(uuid())\n  expenseId       String\n  ledgerAccountId String\n  description     String\n  amountKobo      BigInt\n  vatKobo         BigInt @default(0)\n  sortOrder       Int    @default(0)\n\n  expense       Expense       @relation(fields: [expenseId], references: [id], onDelete: Cascade)\n  ledgerAccount LedgerAccount @relation(fields: [ledgerAccountId], references: [id], onDelete: Restrict)\n\n  @@index([expenseId])\n  @@index([ledgerAccountId])\n}\n\n// One payment out for an expense (a DIRECT expense has exactly one). A reversed payment keeps its row.\nmodel ExpensePayment {\n  id            String        @id @default(uuid())\n  expenseId     String\n  amountKobo    BigInt\n  paidOn        DateTime      @db.Date\n  accountId     String\n  method        PaymentMethod\n  reference     String?\n  paidById      String\n  journalId     String        @unique\n  reversedAt    DateTime?\n  reversedById  String?\n  reverseReason String?\n  createdAt     DateTime      @default(now())\n  updatedAt     DateTime      @updatedAt\n\n  expense Expense       @relation(fields: [expenseId], references: [id], onDelete: Restrict)\n  account LedgerAccount @relation(fields: [accountId], references: [id], onDelete: Restrict)\n  journal JournalEntry  @relation(fields: [journalId], references: [id], onDelete: Restrict)\n\n  @@index([expenseId])\n  @@index([paidOn])\n  @@index([accountId])\n}\n\n// A bill or expense that repeats. A daily job makes a draft (or an approved one) when nextRunDate arrives.\n// lines is a list of { ledgerAccountId, description, amountKobo (digit string) }.\nmodel RecurringExpense {\n  id               String              @id @default(uuid())\n  vendorId         String?\n  kind             ExpenseKind         @default(BILL)\n  payFromAccountId String?\n  description      String\n  lines            Json\n  frequency        RecurrenceFrequency\n  startDate        DateTime            @db.Date\n  endDate          DateTime?           @db.Date\n  nextRunDate      DateTime            @db.Date\n  lastRunAt        DateTime?\n  autoApprove      Boolean             @default(false)\n  isActive         Boolean             @default(true)\n  createdById      String\n  createdAt        DateTime            @default(now())\n  updatedAt        DateTime            @updatedAt\n\n  vendor         Vendor?        @relation(fields: [vendorId], references: [id], onDelete: Restrict)\n  payFromAccount LedgerAccount? @relation(\"RecurringPayFrom\", fields: [payFromAccountId], references: [id], onDelete: Restrict)\n  expenses       Expense[]\n\n  @@index([isActive, nextRunDate])\n}\n\n// What the school plans to earn and spend, to compare with what the books show.\nmodel Budget {\n  id          String       @id @default(uuid())\n  name        String\n  sessionId   String?\n  startDate   DateTime     @db.Date\n  endDate     DateTime     @db.Date\n  status      BudgetStatus @default(DRAFT)\n  createdById String\n  updatedById String?\n  createdAt   DateTime     @default(now())\n  updatedAt   DateTime     @updatedAt\n  deletedAt   DateTime?\n\n  lines BudgetLine[]\n\n  @@index([status])\n  @@index([startDate, endDate])\n  @@index([deletedAt])\n}\n\nmodel BudgetLine {\n  id              String   @id @default(uuid())\n  budgetId        String\n  ledgerAccountId String\n  termId          String?\n  plannedKobo     BigInt\n  note            String?\n  createdAt       DateTime @default(now())\n  updatedAt       DateTime @updatedAt\n\n  budget        Budget        @relation(fields: [budgetId], references: [id], onDelete: Cascade)\n  ledgerAccount LedgerAccount @relation(fields: [ledgerAccountId], references: [id], onDelete: Restrict)\n\n  @@index([budgetId])\n  @@index([ledgerAccountId])\n}\n\n// ──────────────────────────────────────────────────────────────────────────\n// FINANCE PHASE 5: PAYROLL (sensitive). Amounts are whole kobo; rates are basis points (1000 = 10.00%).\n// The school's accountant sets the rules as data; nothing statutory is hardcoded. Staff and ledger accounts are\n// referenced by plain id and checked in code (Finance only reads Staff and adds nothing to it).\n// ──────────────────────────────────────────────────────────────────────────\n\nenum PayComponentType {\n  EARNING\n  DEDUCTION\n  EMPLOYER_CONTRIBUTION\n}\n\nenum PayCalcType {\n  FIXED\n  PERCENT_OF_BASIC\n  PERCENT_OF_GROSS\n  BANDED\n}\n\nenum PayrollRunStatus {\n  DRAFT\n  CALCULATED\n  PENDING_APPROVAL\n  APPROVED\n  PAID\n  CANCELLED\n}\n\nenum PayslipStatus {\n  DRAFT\n  FINAL\n  PAID\n  VOID\n}\n\nenum LoanStatus {\n  ACTIVE\n  CLEARED\n  CANCELLED\n}\n\n// An earning, deduction or employer contribution. defaultValue is kobo for FIXED and basis points for the percent types.\n// bands (BANDED only): [{ \"upToKobo\": \"30000000\" | null, \"rateBp\": 700 }, ...] applied progressively to the month's taxable pay.\nmodel PayComponent {\n  id                 String           @id @default(uuid())\n  name               String\n  code               String           @unique\n  type               PayComponentType\n  calcType           PayCalcType\n  defaultValue       BigInt           @default(0)\n  bands              Json?\n  isTaxable          Boolean          @default(false)\n  isStatutory        Boolean          @default(false)\n  expenseAccountId   String?\n  liabilityAccountId String?\n  isActive           Boolean          @default(true)\n  createdById        String?\n  createdAt          DateTime         @default(now())\n  updatedAt          DateTime         @updatedAt\n  deletedAt          DateTime?\n\n  staffComponents StaffPayComponent[]\n\n  @@index([type])\n  @@index([isActive])\n  @@index([deletedAt])\n}\n\n// What one staff member is paid, from a date. History is kept as dated rows; the current row has no end date.\nmodel StaffPayProfile {\n  id                     String    @id @default(uuid())\n  staffId                String\n  effectiveFrom          DateTime  @db.Date\n  effectiveTo            DateTime? @db.Date\n  basicSalaryKobo        BigInt\n  payFrequency           String    @default(\"MONTHLY\")\n  bankCode               String?\n  bankName               String?\n  accountName            String?\n  accountNumberEncrypted String?\n  accountNumberLast4     String?\n  taxId                  String?\n  pensionId              String?\n  isActive               Boolean   @default(true)\n  createdById            String\n  createdAt              DateTime  @default(now())\n  updatedAt              DateTime  @updatedAt\n\n  components StaffPayComponent[]\n\n  @@index([staffId, effectiveFrom])\n}\n\nmodel StaffPayComponent {\n  id            String  @id @default(uuid())\n  profileId     String\n  componentId   String\n  valueOverride BigInt?\n  isActive      Boolean @default(true)\n\n  profile   StaffPayProfile @relation(fields: [profileId], references: [id], onDelete: Cascade)\n  component PayComponent    @relation(fields: [componentId], references: [id], onDelete: Restrict)\n\n  @@unique([profileId, componentId])\n  @@index([componentId])\n}\n\n// One month's pay for everyone. Only one run per month that is not cancelled (checked in code). Money is posted when it is approved and when it is paid.\nmodel PayrollRun {\n  id                String           @id @default(uuid())\n  runNumber         String           @unique\n  periodYear        Int\n  periodMonth       Int\n  payDate           DateTime         @db.Date\n  status            PayrollRunStatus @default(DRAFT)\n  grossKobo         BigInt           @default(0)\n  deductionsKobo    BigInt           @default(0)\n  employerCostKobo  BigInt           @default(0)\n  netKobo           BigInt           @default(0)\n  staffCount        Int              @default(0)\n  calculatedAt      DateTime?\n  createdById       String\n  submittedAt       DateTime?\n  firstApprovedById String?\n  firstApprovedAt   DateTime?\n  approvedById      String?\n  approvedAt        DateTime?\n  rejectedById      String?\n  rejectedAt        DateTime?\n  rejectionReason   String?\n  paidAt            DateTime?\n  paidById          String?\n  paidOn            DateTime?        @db.Date\n  paidFromAccountId String?\n  paymentReference  String?\n  accrualJournalId  String?          @unique\n  paymentJournalId  String?          @unique\n  cancelledAt       DateTime?\n  cancelledById     String?\n  cancelReason      String?\n  notes             String?\n  version           Int              @default(1)\n  createdAt         DateTime         @default(now())\n  updatedAt         DateTime         @updatedAt\n\n  accrualJournal  JournalEntry?    @relation(\"RunAccrual\", fields: [accrualJournalId], references: [id], onDelete: Restrict)\n  paymentJournal  JournalEntry?    @relation(\"RunPayment\", fields: [paymentJournalId], references: [id], onDelete: Restrict)\n  payslips        Payslip[]\n  salaryTransfers SalaryTransfer[]\n\n  @@index([periodYear, periodMonth])\n  @@index([status])\n}\n\n// One staff member's pay for a run. Numbered and frozen (snapshot) when the run is approved.\nmodel Payslip {\n  id                       String        @id @default(uuid())\n  runId                    String\n  staffId                  String\n  payslipNumber            String?       @unique\n  grossKobo                BigInt\n  totalDeductionsKobo      BigInt\n  netKobo                  BigInt\n  employerContributionKobo BigInt        @default(0)\n  status                   PayslipStatus @default(DRAFT)\n  paidAt                   DateTime?\n  paymentReference         String?\n  snapshot                 Json?\n  emailedAt                DateTime?\n  createdAt                DateTime      @default(now())\n  updatedAt                DateTime      @updatedAt\n\n  run             PayrollRun       @relation(fields: [runId], references: [id], onDelete: Cascade)\n  lines           PayslipLine[]\n  salaryTransfers SalaryTransfer[]\n\n  @@unique([runId, staffId])\n  @@index([staffId])\n}\n\n// kind: BASIC (the basic salary), COMPONENT (a pay component) or LOAN (a loan repayment). The accounts are copied from the component when pay is calculated.\nmodel PayslipLine {\n  id                 String           @id @default(uuid())\n  payslipId          String\n  kind               String           @default(\"COMPONENT\")\n  componentId        String?\n  loanId             String?\n  label              String\n  type               PayComponentType\n  amountKobo         BigInt\n  expenseAccountId   String?\n  liabilityAccountId String?\n  sortOrder          Int              @default(0)\n\n  payslip Payslip @relation(fields: [payslipId], references: [id], onDelete: Cascade)\n\n  @@index([payslipId])\n}\n\nmodel StaffLoan {\n  id                    String     @id @default(uuid())\n  staffId               String\n  principalKobo         BigInt\n  balanceKobo           BigInt\n  monthlyRepaymentKobo  BigInt\n  startYear             Int\n  startMonth            Int\n  status                LoanStatus @default(ACTIVE)\n  reason                String?\n  approvedById          String\n  disbursedOn           DateTime   @db.Date\n  paidFromAccountId     String\n  disbursementJournalId String     @unique\n  cancelledAt           DateTime?\n  cancelledById         String?\n  cancelReason          String?\n  version               Int        @default(1)\n  createdAt             DateTime   @default(now())\n  updatedAt             DateTime   @updatedAt\n\n  disbursementJournal JournalEntry         @relation(fields: [disbursementJournalId], references: [id], onDelete: Restrict)\n  repayments          StaffLoanRepayment[]\n\n  @@index([staffId])\n  @@index([status])\n}\n\nmodel StaffLoanRepayment {\n  id         String    @id @default(uuid())\n  loanId     String\n  payslipId  String\n  amountKobo BigInt\n  reversedAt DateTime?\n  createdAt  DateTime  @default(now())\n\n  loan StaffLoan @relation(fields: [loanId], references: [id], onDelete: Restrict)\n\n  @@unique([loanId, payslipId])\n}\n\n// Tax or pension paid over to the authority: debit the liability account, credit the money account.\nmodel PayrollRemittance {\n  id                 String    @id @default(uuid())\n  liabilityAccountId String\n  periodYear         Int\n  periodMonth        Int\n  amountKobo         BigInt\n  paidOn             DateTime  @db.Date\n  fromAccountId      String\n  reference          String?\n  note               String?\n  journalId          String    @unique\n  createdById        String\n  reversedAt         DateTime?\n  reversedById       String?\n  reverseReason      String?\n  createdAt          DateTime  @default(now())\n\n  journal JournalEntry @relation(fields: [journalId], references: [id], onDelete: Restrict)\n\n  @@index([periodYear, periodMonth])\n}\n\n// ===== FINANCE: BANK RECONCILIATION (phase 6) =====\n// A bank statement is imported as signed lines (money in is positive, money out is negative) and each line is paired with the\n// journal line(s) that record the same money. A month is signed off per money account with BankReconciliation.\n\nenum BankMatchKind {\n  AUTO // paired by the system: same amount, close dates, no other candidate as good\n  MANUAL // paired by a person\n  CREATED // the books did not have it: a journal was made from the bank line (a charge, interest)\n  CLEARED // a book entry with no bank line, set aside with a reason (an opening balance from before the statements start)\n}\n\n// One uploaded file. The same file cannot be imported twice for one account.\nmodel BankStatement {\n  id                 String   @id @default(uuid())\n  ledgerAccountId    String\n  fileName           String?\n  fileHash           String\n  startDate          DateTime @db.Date\n  endDate            DateTime @db.Date\n  openingBalanceKobo BigInt?\n  closingBalanceKobo BigInt?\n  lineCount          Int\n  importedById       String?\n  importedAt         DateTime @default(now())\n\n  ledgerAccount LedgerAccount       @relation(fields: [ledgerAccountId], references: [id], onDelete: Restrict)\n  lines         BankStatementLine[]\n\n  @@unique([ledgerAccountId, fileHash])\n  @@index([ledgerAccountId, endDate])\n}\n\n// One transaction as the bank printed it. dedupeKey stops an overlapping upload creating it twice.\nmodel BankStatementLine {\n  id              String   @id @default(uuid())\n  statementId     String\n  ledgerAccountId String\n  lineNumber      Int\n  txnDate         DateTime @db.Date\n  description     String\n  reference       String?\n  amountKobo      BigInt\n  balanceKobo     BigInt?\n  dedupeKey       String\n  matchGroupId    String?\n  createdAt       DateTime @default(now())\n\n  statement  BankStatement   @relation(fields: [statementId], references: [id], onDelete: Cascade)\n  matchGroup BankMatchGroup? @relation(fields: [matchGroupId], references: [id], onDelete: SetNull)\n\n  @@unique([ledgerAccountId, dedupeKey])\n  @@index([ledgerAccountId, txnDate])\n  @@index([statementId])\n  @@index([matchGroupId])\n}\n\n// A pairing: the bank lines and the journal lines in it add up to the same amount.\nmodel BankMatchGroup {\n  id              String        @id @default(uuid())\n  ledgerAccountId String\n  kind            BankMatchKind\n  note            String?\n  createdById     String?\n  createdAt       DateTime      @default(now())\n\n  ledgerAccount LedgerAccount            @relation(fields: [ledgerAccountId], references: [id], onDelete: Restrict)\n  bankLines     BankStatementLine[]\n  journalLines  BankMatchedJournalLine[]\n\n  @@index([ledgerAccountId, createdAt])\n}\n\n// A journal line can be in at most one pairing (the primary key), so it can never be counted twice.\nmodel BankMatchedJournalLine {\n  journalLineId String @id\n  groupId       String\n\n  group       BankMatchGroup @relation(fields: [groupId], references: [id], onDelete: Cascade)\n  journalLine JournalLine    @relation(fields: [journalLineId], references: [id], onDelete: Restrict)\n\n  @@index([groupId])\n}\n\n// The sign-off: this money account agreed with its bank at the end of this month. Reopening deletes the row (the audit trail keeps why).\nmodel BankReconciliation {\n  id                   String   @id @default(uuid())\n  ledgerAccountId      String\n  periodId             String\n  statementBalanceKobo BigInt\n  bookBalanceKobo      BigInt\n  outstandingBookKobo  BigInt\n  note                 String?\n  completedById        String?\n  completedAt          DateTime @default(now())\n\n  ledgerAccount LedgerAccount @relation(fields: [ledgerAccountId], references: [id], onDelete: Restrict)\n  period        FinancePeriod @relation(fields: [periodId], references: [id], onDelete: Restrict)\n\n  @@unique([ledgerAccountId, periodId])\n  @@index([periodId])\n}\n\n// ============================================================================\n// FINANCE: GATEWAY SETTLEMENTS (phase 6)\n// ============================================================================\n\n// One payout from the payment gateway to the school's bank. The journal is Dr bank (net) + Dr bank charges (fee) / Cr online clearing (gross).\nmodel GatewaySettlement {\n  id            String    @id @default(uuid())\n  provider      String    @default(\"paystack\")\n  reference     String\n  settledOn     DateTime  @db.Date\n  grossKobo     BigInt\n  feeKobo       BigInt\n  netKobo       BigInt\n  accountId     String\n  journalId     String    @unique\n  itemCount     Int\n  note          String?\n  recordedById  String?\n  createdAt     DateTime  @default(now())\n  reversedAt    DateTime?\n  reversedById  String?\n  reverseReason String?\n\n  account LedgerAccount           @relation(fields: [accountId], references: [id], onDelete: Restrict)\n  journal JournalEntry            @relation(fields: [journalId], references: [id], onDelete: Restrict)\n  items   GatewaySettlementItem[]\n\n  @@unique([provider, reference])\n  @@index([settledOn])\n}\n\n// An online payment that a settlement paid out. A payment can be in at most one live settlement (reversing the settlement deletes these rows).\nmodel GatewaySettlementItem {\n  id           String @id @default(uuid())\n  settlementId String\n  paymentId    String @unique\n  amountKobo   BigInt\n  feeKobo      BigInt\n\n  settlement GatewaySettlement @relation(fields: [settlementId], references: [id], onDelete: Cascade)\n  payment    Payment           @relation(fields: [paymentId], references: [id], onDelete: Restrict)\n\n  @@index([settlementId])\n}\n\n// ============================================================================\n// PAYROLL: SALARY TRANSFERS (phase 6). One row per attempt to pay one payslip by bank transfer.\n// The row exists BEFORE the provider is called; only a confirmed outcome (webhook or verify) makes it SUCCESS and posts the books.\n// ============================================================================\n\nenum SalaryTransferStatus {\n  PENDING // created, nothing sent\n  SENDING // claimed by a sender, the provider call is in flight\n  PROCESSING // the provider accepted it and is still moving the money\n  UNKNOWN // the provider call ended without an answer: never resend, verify\n  SUCCESS // confirmed paid\n  FAILED // confirmed not paid (a retry makes a new attempt)\n  REVERSED // paid, then returned by the bank\n  CANCELLED // stopped before sending\n}\n\nmodel SalaryTransfer {\n  id                     String               @id @default(uuid())\n  runId                  String\n  payslipId              String\n  staffId                String\n  attempt                Int                  @default(1)\n  reference              String               @unique\n  amountKobo             BigInt\n  status                 SalaryTransferStatus @default(PENDING)\n  bankCode               String\n  bankName               String?\n  accountName            String\n  accountNumberEncrypted String\n  accountLast4           String\n  recipientCode          String?\n  transferCode           String?\n  fromAccountId          String\n  failureReason          String?\n  initiatedById          String\n  sentAt                 DateTime?\n  confirmedAt            DateTime?\n  journalId              String?              @unique\n  reversalJournalId      String?\n  createdAt              DateTime             @default(now())\n  updatedAt              DateTime             @updatedAt\n\n  run         PayrollRun    @relation(fields: [runId], references: [id], onDelete: Restrict)\n  payslip     Payslip       @relation(fields: [payslipId], references: [id], onDelete: Restrict)\n  fromAccount LedgerAccount @relation(\"SalaryTransferFrom\", fields: [fromAccountId], references: [id], onDelete: Restrict)\n  journal     JournalEntry? @relation(\"SalaryTransferJournal\", fields: [journalId], references: [id], onDelete: Restrict)\n\n  @@unique([payslipId, attempt])\n  @@index([runId])\n  @@index([status])\n}\n\n// ── Grades setup: grading scales and assessment schemes, one per level (level empty = the default for all levels) ──\nenum AssessmentKind {\n  ca\n  exam\n}\n\nmodel GradingScale {\n  id        String   @id @default(uuid())\n  name      String\n  level     String? // primary | jss | ss, or empty for the default. One scale per level (SQL unique index)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  bands GradingBand[]\n}\n\n// A band starts at minScore and runs up to the next band's minScore (the top band reaches 100)\nmodel GradingBand {\n  id        String   @id @default(uuid())\n  scaleId   String\n  minScore  Float\n  grade     String\n  remark    String\n  isPass    Boolean  @default(true)\n  createdAt DateTime @default(now())\n\n  scale GradingScale @relation(fields: [scaleId], references: [id], onDelete: Cascade)\n\n  @@unique([scaleId, minScore])\n}\n\nmodel AssessmentScheme {\n  id        String   @id @default(uuid())\n  name      String\n  level     String? // primary | jss | ss, or empty for the default. One scheme per level (SQL unique index)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  components AssessmentComponent[]\n}\n\n// The maximum scores of one scheme's components add up to 100\nmodel AssessmentComponent {\n  id        String         @id @default(uuid())\n  schemeId  String\n  name      String\n  kind      AssessmentKind\n  maxScore  Float\n  position  Int\n  createdAt DateTime       @default(now())\n\n  scheme AssessmentScheme @relation(fields: [schemeId], references: [id], onDelete: Cascade)\n\n  @@unique([schemeId, position])\n}\n\n// ── Mark sheets: one subject, in one class, for one term ──\nenum ResultSheetStatus {\n  draft\n  submitted\n  approved\n  published\n  locked\n}\n\nmodel ResultSheet {\n  id             String            @id @default(uuid())\n  classSubjectId String            @unique\n  status         ResultSheetStatus @default(draft)\n  components     Json // the parts of the score, copied from the school's scheme when the sheet is created: [{ position, name, kind, maxScore }]\n  scale          Json? // the grading scale used, frozen when published: [{ minScore, grade, remark, isPass }]\n  submittedAt    DateTime?\n  submittedById  String?\n  approvedAt     DateTime?\n  approvedById   String?\n  publishedAt    DateTime?\n  publishedById  String?\n  lockedAt       DateTime?\n  lockedById     String?\n  reopenedAt     DateTime?\n  reopenedById   String?\n  reopenReason   String?\n  createdAt      DateTime          @default(now())\n  updatedAt      DateTime          @updatedAt\n\n  classSubject ClassSubject @relation(fields: [classSubjectId], references: [id])\n  grades       Grade[]\n\n  @@index([status])\n}\n\n// One score of one student for one part (position) of the sheet's scheme. Not entered = no row or an empty score.\nmodel GradeScore {\n  id       String  @id @default(uuid())\n  gradeId  String\n  position Int\n  score    Float?\n  isAbsent Boolean @default(false)\n\n  grade Grade @relation(fields: [gradeId], references: [id], onDelete: Cascade)\n\n  @@unique([gradeId, position])\n}\n"
}

